package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.time.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;

/** Recorded outage evidence and explicit interval arithmetic, independent of monitoring claims. */
final class ServiceOutages {
 static final long DAY=86400000L;
 private ServiceOutages() {}
 static void staff(Store.Db db){if(!Set.of("admin","agent").contains(db.viewerRole))throw new Failure(403,"Operational staff permission required");}
 static long time(Object value,long maximum){String text=WorkJobs.text(value,40);Instant parsed;try{parsed=Instant.parse(text);}catch(DateTimeException invalid){throw new Failure(400,"Use a valid UTC instant");}require(text.endsWith("Z") && !parsed.isBefore(Instant.EPOCH) && !parsed.isAfter(Instant.ofEpochMilli(maximum)) && parsed.getNano()%1000000==0,"Use a bounded UTC instant with millisecond precision");return parsed.toEpochMilli();}
 static String stamp(long value){return Instant.ofEpochMilli(value).toString();}
 static String status(Map<String,Object> row,long now){if(((Number)row.get("cancelled")).intValue()==1)return "cancelled";if(((Number)row.get("begin_ms")).longValue()>now)return "scheduled";long end=((Number)row.get("end_ms")).longValue();return end==0 || end>now?"ongoing":"ended";}
 static long duration(List<Map<String,Object>> rows,String type,long begin,long end){var intervals=new ArrayList<long[]>();for(var row:rows){if(((Number)row.get("cancelled")).intValue()!=0 || !row.get("kind").equals(type))continue;long storedEnd=((Number)row.get("end_ms")).longValue(),left=Math.max(begin,((Number)row.get("begin_ms")).longValue()),right=Math.min(end,storedEnd==0?end:storedEnd);if(left<right)intervals.add(new long[]{left,right});}intervals.sort(Comparator.comparingLong(a->a[0]));long total=0,left=0,right=0;for(long[] interval:intervals){if(interval[0]>right){total+=right-left;left=interval[0];right=interval[1];}else right=Math.max(right,interval[1]);}return total+right-left;}
 static Map<String,Object> page(Store.Db db,String id,Map<String,String> args,long now)throws SQLException {
  staff(db);var record=Service.readRecord(db,"cmdb_ci",id);require(Set.of("start","end","offset").containsAll(args.keySet()) && args.containsKey("start")==args.containsKey("end"),"Provide both reporting start and end, with optional offset");int offset=Service.number(args.getOrDefault("offset","0"),0,1000);long begin=args.containsKey("start")?time(args.get("start"),now):Math.max(0,now-30*DAY),end=args.containsKey("end")?time(args.get("end"),now):now;require(begin<end && end-begin<=366*DAY,"Choose a positive reporting window of at most 366 days");var rows=db.all("SELECT * FROM os_ci_outage WHERE record_id=? ORDER BY begin_ms DESC,outage_id",id);long downtime=duration(rows,"outage",begin,end),planned=duration(rows,"planned",begin,end),degraded=duration(rows,"degradation",begin,end);String availability=BigDecimal.valueOf(end-begin-downtime).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(end-begin),4,RoundingMode.HALF_UP).toPlainString();int rank=0,index=0;String current="no_recorded_outage";var entries=new ArrayList<Map<String,Object>>();for(var row:rows){String state=status(row,now);if(state.equals("ongoing")){int priority=Map.of("planned",1,"degradation",2,"outage",3).get(row.get("kind"));if(priority>rank){rank=priority;current=row.get("kind").toString();}}if(index++>=offset && entries.size()<100){var entry=new LinkedHashMap<>(row);entry.remove("fingerprint");entry.put("begin",stamp(((Number)row.get("begin_ms")).longValue()));long finish=((Number)row.get("end_ms")).longValue();entry.put("end",finish==0?"":stamp(finish));entry.put("status",state);entry.put("history",db.all("SELECT revision,detail FROM os_outage_history WHERE outage_id=? ORDER BY revision DESC",row.get("outage_id")));entries.add(entry);}}return map("record",FieldAccess.serialize(db,record),"outages",entries,"truncated",rows.size()>100,"total",rows.size(),"offset",offset,"previous_offset",Math.max(0,offset-100),"next_offset",offset+entries.size()<rows.size()?offset+100:-1,"current_status",current,"can_edit",RecordPolicy.allows(Service.schema(db,"cmdb_ci"),"update",db.viewerRole),"request_id",Values.id(),"now",stamp(now),"report",map("start",stamp(begin),"end",stamp(end),"window_ms",end-begin,"unplanned_ms",downtime,"planned_ms",planned,"degraded_ms",degraded,"recorded_availability",availability));
 }
 static Map<String,Object> save(Store.Db db,String id,Object input,long now)throws Exception {
  staff(db);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var record=Service.record(db,"cmdb_ci",id);RecordPolicy.require(Service.schema(db,"cmdb_ci"),"update",db.viewerRole);var body=object(input);String operation=WorkJobs.text(body.get("operation"),20);require(Set.of("create","close","cancel").contains(operation),"Choose create, close or cancel");ProblemInvestigations.revision(body.get("record_revision"),record.get("revision"));String actor=Service.account(db,db.viewerId).get("name").toString(),outageId;int revision;Map<String,Object> evidence;
  if(operation.equals("create")){require(body.keySet().equals(Set.of("operation","record_revision","request_id","kind","begin","end","summary","evidence")),"Provide the reviewed outage evidence only");String request=WorkJobs.text(body.get("request_id"),32),kind=WorkJobs.text(body.get("kind"),20),summary=WorkJobs.text(body.get("summary"),160),detail=WorkJobs.text(body.get("evidence"),4000);require(request.matches("[0-9a-f]{32}"),"Use an opaque request identity");require(Set.of("outage","planned","degradation").contains(kind),"Choose outage, planned maintenance or degradation");boolean planned=kind.equals("planned");long maximum=now+(planned?366*DAY:0),begin=time(body.get("begin"),maximum);require(body.get("end") instanceof String,"Provide an end instant or empty text");String endText=body.get("end").toString();require(!planned || !endText.isEmpty(),"Planned maintenance needs an end");long end=endText.isEmpty()?0:time(endText,maximum);require(endText.isEmpty() || end>begin,"End must follow begin");require(!planned || end-begin<=366*DAY,"Planned maintenance is limited to 366 days");evidence=map("operation",operation,"kind",kind,"begin",stamp(begin),"end",end==0?"":stamp(end),"summary",summary,"evidence",detail,"record_revision",body.get("record_revision"));String fingerprint=DigestUtils.sha256Hex(JSON.writeValueAsString(evidence));var prior=db.one("SELECT outage_id,fingerprint FROM os_ci_outage WHERE record_id=? AND request_id=?",id,request);if(prior!=null){if(!prior.get("fingerprint").equals(fingerprint))throw new Failure(409,"Request identity already represents different outage evidence");var result=page(db,id,Map.of(),now);result.put("outage_id",prior.get("outage_id"));return result;}require(db.count("SELECT COUNT(*) FROM os_ci_outage WHERE record_id=?",id)<1000,"This CI has reached retained outage capacity");outageId=Values.id();revision=1;db.update("INSERT INTO os_ci_outage(outage_id,record_id,request_id,fingerprint,kind,summary,begin_ms,end_ms,cancelled,revision) VALUES(?,?,?,?,?,?,?,?,0,1)",outageId,id,request,fingerprint,kind,summary,begin,end);
  }else{Set<String> fields=new HashSet<>(Set.of("operation","record_revision","outage_id","revision","evidence"));if(operation.equals("close"))fields.add("end");require(body.keySet().equals(fields),"Provide current outage revision and evidence only");outageId=WorkJobs.text(body.get("outage_id"),32);var prior=db.one("SELECT * FROM os_ci_outage WHERE outage_id=? AND record_id=?",outageId,id);if(prior==null)throw new Failure(404,"Outage not found");ProblemInvestigations.revision(body.get("revision"),prior.get("revision"));if(((Number)prior.get("cancelled")).intValue()!=0)throw new Failure(409,"This outage entry is cancelled");String detail=WorkJobs.text(body.get("evidence"),4000);revision=((Number)prior.get("revision")).intValue()+1;evidence=map("operation",operation,"evidence",detail,"record_revision",body.get("record_revision"));if(operation.equals("close")){long previousEnd=((Number)prior.get("end_ms")).longValue();if(previousEnd!=0 && (!prior.get("kind").equals("planned") || previousEnd<=now))throw new Failure(409,"Recovery is already recorded");long end=time(body.get("end"),now);require(end>((Number)prior.get("begin_ms")).longValue(),"Recovery must follow outage begin");db.update("UPDATE os_ci_outage SET end_ms=?,revision=? WHERE outage_id=?",end,revision,outageId);evidence.put("end",stamp(end));}else db.update("UPDATE os_ci_outage SET cancelled=1,revision=? WHERE outage_id=?",revision,outageId);}
  evidence.putAll(map("actor",actor,"actor_id",db.viewerId,"recorded_at",stamp(now)));db.update("INSERT INTO os_outage_history(outage_id,revision,detail) VALUES(?,?,?)",outageId,revision,JSON.writeValueAsString(evidence));Service.audit(db,record,actor,"outage."+operation,map("outage_id",outageId,"revision",revision));var result=page(db,id,Map.of(),now);result.put("outage_id",outageId);return result;
 }
 static void deleting(Store.Db db,String id)throws SQLException{if(db.count("SELECT COUNT(*) FROM os_ci_outage WHERE record_id=?",id)>0)throw new Failure(409,"Retain CIs with recorded outage evidence");}
}
